// Extract the requested date from webhook
const checkDate = $input.first().json.query?.checkavail || $input.first().json.body?.checkavail || $input.first().json.checkavail;

if (!checkDate) {
  throw new Error('No date provided in checkavail field');
}

// Parse the date
const requestedDate = new Date(checkDate);
const dayOfWeek = requestedDate.getDay(); // 0=Sun, 1=Mon, 2=Tue, 3=Wed, 4=Thu, 5=Fri, 6=Sat
const dayNames = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

// Damu's availability: Monday-Thursday, 8am-4pm Dubai time
const isWorkingDay = dayOfWeek >= 1 && dayOfWeek <= 4; // Mon-Thu

// Format dates for API calls
const year = requestedDate.getFullYear();
const month = String(requestedDate.getMonth() + 1).padStart(2, '0');
const day = String(requestedDate.getDate()).padStart(2, '0');

// Zoho Calendar format: YYYYMMDDTHHmmss
const zohoStartDate = `${year}${month}${day}T040000`; // 4am UTC = 8am Dubai
const zohoEndDate = `${year}${month}${day}T120000`; // 12pm UTC = 4pm Dubai

// Google Calendar format: ISO 8601
const googleStartDate = `${year}-${month}-${day}T08:00:00+04:00`; // 8am Dubai
const googleEndDate = `${year}-${month}-${day}T16:00:00+04:00`; // 4pm Dubai

// Zoho Bookings format: dd-MMM-yyyy
const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const zohoBookingsDate = `${day}-${months[requestedDate.getMonth()]}-${year}`;

return {
  json: {
    originalDate: checkDate,
    dayOfWeek: dayNames[dayOfWeek],
    dayNumber: dayOfWeek,
    isWorkingDay: isWorkingDay,
    zohoCalendarStart: zohoStartDate,
    zohoCalendarEnd: zohoEndDate,
    googleCalendarStart: googleStartDate,
    googleCalendarEnd: googleEndDate,
    zohoBookingsDate: zohoBookingsDate,
    workingHoursStart: '08:00',
    workingHoursEnd: '16:00',
    timezone: 'Asia/Dubai'
  }
};

