// Get the parsed date info
const dateInfo = $('Parse Date & Check Working Day').first().json;

// Extract Zoho Calendar busy times
let zohoBusyTimes = [];
try {
  const zohoCalData = $('Zoho Calendar - Get Busy Times').first().json;
  if (zohoCalData?.freebusy) {
    zohoBusyTimes = zohoCalData.freebusy;
  } else if (zohoCalData?.data) {
    zohoBusyTimes = zohoCalData.data;
  }
} catch (e) {
  console.log('No Zoho Calendar data:', e.message);
}

// Extract Zoho Bookings available slots
let zohoAvailableSlots = [];
let slotsNotAvailable = false;
try {
  const bookingsData = $('Zoho Bookings - Get Available Slots').first().json;

  // Handle different response structures
  if (bookingsData?.response?.returnvalue?.data) {
    const data = bookingsData.response.returnvalue.data;
    if (typeof data === 'string' && data.includes('Slots Not Available')) {
      slotsNotAvailable = true;
    } else {
      zohoAvailableSlots = Array.isArray(data) ? data : [data];
    }
  } else if (bookingsData?.data) {
    zohoAvailableSlots = bookingsData.data;
  }
} catch (e) {
  console.log('No Zoho Bookings data:', e.message);
}

return {
  json: {
    dateInfo: dateInfo,
    zohoBusyTimes: zohoBusyTimes,
    zohoAvailableSlots: zohoAvailableSlots,
    slotsNotAvailable: slotsNotAvailable,
    rawData: {
      zohoCalendar: JSON.stringify(zohoBusyTimes),
      zohoBookings: JSON.stringify(zohoAvailableSlots)
    }
  }
};

